using System.Data;
using HRM.BUS;
using HRM.DAL;
using HRM.DTO;
namespace HRM.GUI;
public sealed class MainForm:Form
{
    readonly DepartmentService departments=new(); readonly EmployeeService employees=new(); readonly AttendanceService attendance=new(); readonly PayrollService payroll=new();
    readonly TabControl tabs=new(){Dock=DockStyle.Fill}; readonly DataGridView empGrid=Grid(),deptGrid=Grid(),attGrid=Grid(),payGrid=Grid();
    readonly TextBox search=new(){Width=220,PlaceholderText="Tên / CCCD / mã nhân viên"}; readonly ComboBox filterDept=new(){Width=180,DropDownStyle=ComboBoxStyle.DropDownList};
    readonly DateTimePicker monthPicker=new(){Format=DateTimePickerFormat.Custom,CustomFormat="MM/yyyy",ShowUpDown=true}; readonly DateTimePicker payrollMonthPicker=new(){Format=DateTimePickerFormat.Custom,CustomFormat="MM/yyyy",ShowUpDown=true}; DataTable? attendanceTable;
    public MainForm(){Text="HỆ THỐNG QUẢN LÝ NHÂN SỰ & TÍNH LƯƠNG - BÀI 6.2";Width=1250;Height=780;MinimumSize=new(1000,650);StartPosition=FormStartPosition.CenterScreen;Controls.Add(tabs);tabs.TabPages.Add(BuildEmployeeTab());tabs.TabPages.Add(BuildDepartmentTab());tabs.TabPages.Add(BuildAttendanceTab());tabs.TabPages.Add(BuildPayrollTab());Shown+=(_,_)=>RunSafe(()=>{Db.TestConnection();LoadDepartments();LoadEmployees();});}
    static DataGridView Grid()=>new(){Dock=DockStyle.Fill,ReadOnly=false,AllowUserToAddRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,RowHeadersVisible=false};
    static Button Btn(string text,int width=120)=>new(){Text=text,Width=width,Height=32,Margin=new Padding(5)};
    TabPage Page(string title)=>new(title);
    TabPage BuildEmployeeTab(){var p=Page("Nhân viên");var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=48,Padding=new Padding(5)};var bSearch=Btn("Tìm kiếm");bSearch.Click+=(_,_)=>RunSafe(LoadEmployees);var bAdd=Btn("Thêm nhân viên");bAdd.Click+=(_,_)=>RunSafe(()=>EditEmployee(null));var bEdit=Btn("Sửa nhân viên");bEdit.Click+=(_,_)=>RunSafe(()=>EditSelectedEmployee());var bDel=Btn("Xóa nhân viên");bDel.Click+=(_,_)=>RunSafe(DeleteEmployee);var bRefresh=Btn("Tải lại");bRefresh.Click+=(_,_)=>RunSafe(LoadEmployees);bar.Controls.AddRange([search,filterDept,bSearch,bAdd,bEdit,bDel,bRefresh]);p.Controls.Add(empGrid);p.Controls.Add(bar);return p;}
    TabPage BuildDepartmentTab(){var p=Page("Phòng ban");var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=48,Padding=new Padding(5)};var a=Btn("Thêm phòng ban");a.Click+=(_,_)=>RunSafe(()=>EditDepartment(null));var e=Btn("Sửa phòng ban");e.Click+=(_,_)=>RunSafe(EditSelectedDepartment);var d=Btn("Xóa phòng ban");d.Click+=(_,_)=>RunSafe(DeleteDepartment);var r=Btn("Tải lại");r.Click+=(_,_)=>RunSafe(LoadDepartments);bar.Controls.AddRange([a,e,d,r]);p.Controls.Add(deptGrid);p.Controls.Add(bar);return p;}
    TabPage BuildAttendanceTab(){var p=Page("Chấm công (Disconnected)");var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=50,Padding=new Padding(5)};var load=Btn("Tải chấm công");load.Click+=(_,_)=>RunSafe(LoadAttendance);var save=Btn("Lưu chấm công",140);save.Click+=(_,_)=>RunSafe(SaveAttendance);bar.Controls.AddRange([new Label{Text="Tháng/Năm:",AutoSize=true,Padding=new Padding(5,9,0,0)},monthPicker,load,save]);p.Controls.Add(attGrid);p.Controls.Add(bar);attGrid.DataError+=(_,e)=>{MessageBox.Show("Dữ liệu nhập không hợp lệ.");e.ThrowException=false;};return p;}
    TabPage BuildPayrollTab(){var p=Page("Tính lương & chốt lương");var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=50,Padding=new Padding(5)};var load=Btn("Xem bảng lương");load.Click+=(_,_)=>RunSafe(LoadPayroll);var close=Btn("Chốt lương tháng",160);close.Click+=(_,_)=>RunSafe(ClosePayroll);bar.Controls.AddRange([new Label{Text="Tháng/Năm:",AutoSize=true,Padding=new Padding(5,9,0,0)},payrollMonthPicker,load,close]);p.Controls.Add(payGrid);p.Controls.Add(bar);var note=new Label{Dock=DockStyle.Bottom,Height=42,Text="Công thức: (Lương cơ bản × Hệ số / 22) × Ngày công + Giờ OT × 50.000. Chốt lương sẽ khóa chấm công tháng đó.",Padding=new Padding(8)};p.Controls.Add(note);return p;}
    string Month=>monthPicker.Value.ToString("MM/yyyy"); string PayrollMonth=>payrollMonthPicker.Value.ToString("MM/yyyy");
    void LoadDepartments(){var list=departments.GetAll();deptGrid.DataSource=list;var opts=new List<Department>{new(){MaPB=0,TenPB="-- Tất cả phòng ban --"}};opts.AddRange(list);filterDept.DataSource=opts;filterDept.DisplayMember=nameof(Department.TenPB);filterDept.ValueMember=nameof(Department.MaPB);}
    void LoadEmployees(){int? pb=filterDept.SelectedValue is int v&&v>0?v:null;empGrid.DataSource=employees.Search(search.Text,pb);}
    void EditEmployee(Employee? e){bool isNew=e==null;e??=new Employee{HeSoLuong=1.0,LuongCoBan=10000000};using var f=new Form{Text=isNew?"Thêm nhân viên":"Sửa nhân viên",Width=440,Height=430,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false};var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(12),ColumnCount=2,RowCount=7};layout.ColumnStyles.Add(new(SizeType.Absolute,125));layout.ColumnStyles.Add(new(SizeType.Percent,100));string[] labels=["Họ tên","Ngày sinh","CCCD","Phòng ban","Lương cơ bản","Hệ số lương"];var name=new TextBox{Dock=DockStyle.Fill,Text=e.HoTen};var dob=new DateTimePicker{Dock=DockStyle.Fill,Format=DateTimePickerFormat.Custom,CustomFormat="dd/MM/yyyy",ShowCheckBox=true,Checked=e.NgaySinh.HasValue};if(e.NgaySinh.HasValue)dob.Value=e.NgaySinh.Value;var cccd=new TextBox{Dock=DockStyle.Fill,Text=e.CCCD??""};var pb=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList,DataSource=departments.GetAll(),DisplayMember=nameof(Department.TenPB),ValueMember=nameof(Department.MaPB)};if(e.MaPB>0)pb.SelectedValue=e.MaPB;var salary=new NumericUpDown{Dock=DockStyle.Fill,Maximum=1000000000,Minimum=1,DecimalPlaces=2,Value=Math.Min(1000000000m,Math.Max(1,e.LuongCoBan))};var factor=new NumericUpDown{Dock=DockStyle.Fill,Maximum=100,Minimum=0.01m,DecimalPlaces=2,Increment=0.1m,Value=(decimal)Math.Max(.01,e.HeSoLuong)};Control[] ctrls=[name,dob,cccd,pb,salary,factor];for(int i=0;i<labels.Length;i++){layout.Controls.Add(new Label{Text=labels[i],AutoSize=true,Anchor=AnchorStyles.Left},0,i);layout.Controls.Add(ctrls[i],1,i);}var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=48,FlowDirection=FlowDirection.RightToLeft};var ok=Btn("Lưu");ok.Click+=(_,_)=>{try{if(pb.SelectedValue==null)throw new Exception("Hãy tạo phòng ban trước.");e.HoTen=name.Text;e.NgaySinh=dob.Checked?dob.Value.Date:null;e.CCCD=string.IsNullOrWhiteSpace(cccd.Text)?null:cccd.Text.Trim();e.MaPB=(int)pb.SelectedValue;e.LuongCoBan=salary.Value;e.HeSoLuong=(double)factor.Value;employees.Save(e,isNew);f.DialogResult=DialogResult.OK;f.Close();}catch(Exception ex){MessageBox.Show(ex.Message,"Không thể lưu",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};var cancel=Btn("Hủy");cancel.Click+=(_,_)=>f.Close();buttons.Controls.AddRange([ok,cancel]);f.Controls.Add(layout);f.Controls.Add(buttons);if(f.ShowDialog(this)==DialogResult.OK)LoadEmployees();}
    void EditSelectedEmployee(){if(empGrid.CurrentRow?.DataBoundItem is not Employee e)throw new Exception("Hãy chọn nhân viên cần sửa.");EditEmployee(e);}
    void DeleteEmployee(){if(empGrid.CurrentRow?.DataBoundItem is not Employee e)throw new Exception("Hãy chọn nhân viên cần xóa.");if(MessageBox.Show($"Xóa nhân viên {e.HoTen}?","Xác nhận",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;employees.Delete(e.MaNV);LoadEmployees();}
    void EditDepartment(Department? d){bool n=d==null;d??=new Department();using var f=new Form{Text=n?"Thêm phòng ban":"Sửa phòng ban",Width=420,Height=220,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false};var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(12),ColumnCount=2,RowCount=2};layout.ColumnStyles.Add(new(SizeType.Absolute,100));layout.ColumnStyles.Add(new(SizeType.Percent,100));var name=new TextBox{Dock=DockStyle.Fill,Text=d.TenPB};var desc=new TextBox{Dock=DockStyle.Fill,Text=d.MoTa??""};layout.Controls.Add(new Label{Text="Tên phòng ban",AutoSize=true,Anchor=AnchorStyles.Left},0,0);layout.Controls.Add(name,1,0);layout.Controls.Add(new Label{Text="Mô tả",AutoSize=true,Anchor=AnchorStyles.Left},0,1);layout.Controls.Add(desc,1,1);var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=45,FlowDirection=FlowDirection.RightToLeft};var ok=Btn("Lưu");ok.Click+=(_,_)=>{if(string.IsNullOrWhiteSpace(name.Text)){MessageBox.Show("Tên phòng ban không được để trống.");return;}d.TenPB=name.Text.Trim();d.MoTa=string.IsNullOrWhiteSpace(desc.Text)?null:desc.Text.Trim();f.DialogResult=DialogResult.OK;f.Close();};var cancel=Btn("Hủy");cancel.Click+=(_,_)=>f.Close();buttons.Controls.AddRange([ok,cancel]);f.Controls.Add(layout);f.Controls.Add(buttons);if(f.ShowDialog(this)==DialogResult.OK){departments.Save(d,n);LoadDepartments();}}
    void EditSelectedDepartment(){if(deptGrid.CurrentRow?.DataBoundItem is not Department d)throw new Exception("Hãy chọn phòng ban.");EditDepartment(d);}
    void DeleteDepartment(){if(deptGrid.CurrentRow?.DataBoundItem is not Department d)throw new Exception("Hãy chọn phòng ban.");if(MessageBox.Show($"Xóa phòng ban {d.TenPB}?","Xác nhận",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;departments.Delete(d.MaPB);LoadDepartments();}
    void LoadAttendance(){if(attendance.IsLocked(Month))throw new Exception("Tháng này đã chốt lương, chấm công ở chế độ chỉ đọc.");attendanceTable=attendance.Load(Month);attGrid.DataSource=attendanceTable;foreach(string col in new[]{"MaCong","ThangNam"})if(attGrid.Columns.Contains(col))attGrid.Columns[col].Visible=false;if(attGrid.Columns.Contains("HoTen"))attGrid.Columns["HoTen"].ReadOnly=true;if(attGrid.Columns.Contains("MaNV"))attGrid.Columns["MaNV"].ReadOnly=true;}
    void SaveAttendance(){if(attendanceTable==null)throw new Exception("Hãy tải bảng chấm công trước.");attGrid.EndEdit();int count=attendance.Save(attendanceTable,Month);MessageBox.Show($"Đã đồng bộ {count} dòng chấm công bằng SqlDataAdapter.Update().","Thành công");LoadAttendance();}
    void LoadPayroll(){payGrid.DataSource=payroll.GetMonth(PayrollMonth);}
    void ClosePayroll(){if(MessageBox.Show($"Chốt lương tháng {PayrollMonth}? Sau khi chốt, dữ liệu chấm công sẽ bị khóa.","Xác nhận chốt lương",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;int count=payroll.Close(PayrollMonth);LoadPayroll();MessageBox.Show($"Đã chốt lương cho {count} nhân viên. Dữ liệu tháng {PayrollMonth} đã khóa.","Hoàn tất");}
    void RunSafe(Action action){try{action();}catch(Exception ex){MessageBox.Show(ex.Message,"Thông báo",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
}
